const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Approximate polygon for Bobiri Forest Reserve, Ghana
  // Source: Based on general location (6.67°N, 1.25°W)
  const geometry = ee.Geometry.Polygon(
    [[[-1.300, 6.700],
      [-1.190, 6.700],
      [-1.190, 6.640],
      [-1.300, 6.640],
      [-1.300, 6.700]]]);

  const treeCoverThreshold = 10; // Percentage: >=10% tree cover is considered forest

  // 2. Data Acquisition
  const gfc = ee.Image('UMD/hansen/global_forest_change_v1_11');

  // Check if GFC image exists
  try {
    const bandNames = gfc.bandNames().getInfo();
    if (!bandNames || bandNames.length === 0) {
      console.log("Error: Hansen GFC image not found or has no bands.");
      console.log("C1");
      return;
    }
  } catch (e) {
    console.log(`Error accessing Hansen GFC image: ${e.message}`);
    console.log("C1");
    return;
  }

  const treecover2000 = gfc.select('treecover2000');
  const loss = gfc.select('loss');
  const lossyear = gfc.select('lossyear');

  // Function to calculate forest area for a given year
  const calculateForestArea = (year) => {
    // Initial forest cover based on 2000 treecover and threshold
    let forest = treecover2000.gte(treeCoverThreshold).rename('forest');

    // Mask out areas that lost forest cover up to the specified year
    // lossyear band is 1 for 2001, 2 for 2002, ..., 23 for 2023.
    const yearCode = year - 2000;
    const lostBeforeOrInYear = loss.and(lossyear.lte(yearCode));
    forest = forest.updateMask(lostBeforeOrInYear.eq(0)); // Mask where loss occurred

    // Calculate area of remaining forest pixels
    // Multiply by pixel area to get square meters
    const forestArea = forest.multiply(ee.Image.pixelArea());

    return forestArea;
  };

  // Calculate forest area for 2003
  const forestArea2003 = calculateForestArea(2003);
  const result2003 = forestArea2003.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: 30, // Hansen data resolution is 30m
    maxPixels: 1e9
  });

  // Calculate forest area for 2023
  const forestArea2023 = calculateForestArea(2023);
  const result2023 = forestArea2023.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry,
    scale: 30,
    maxPixels: 1e9
  });

  // Get results and convert from m^2 to km^2
  let area_sqm_2003 = result2003.get('forest').getInfo();
  let area_sqm_2023 = result2023.get('forest').getInfo();

  // 3. Validation & Final Answer
  if (area_sqm_2003 === null || area_sqm_2023 === null || isNaN(area_sqm_2003) || isNaN(area_sqm_2023)) {
    console.log("Calculation failure: Area is null or NaN.");
    console.log("C3");
    return;
  }

  const area_km2_2003 = area_sqm_2003 / 1e6;
  const area_km2_2023 = area_sqm_2023 / 1e6;

  // Check for C2 (No Valid Pixels) - if initial treecover condition results in no forest.
  const initialForestPixels2003 = forestArea2003.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 30,
    maxPixels: 1e9
  }).get('forest').getInfo();

  const initialForestPixels2023 = forestArea2023.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 30,
    maxPixels: 1e9
  }).get('forest').getInfo();

  if (initialForestPixels2003 === 0 && initialForestPixels2023 === 0) {
      console.log("No valid forest pixels found for both periods within the geometry and threshold.");
      console.log("C2");
      return;
  } else if (initialForestPixels2003 === 0) {
      console.log("No valid forest pixels found for 2003 within the geometry and threshold.");
      console.log("C2");
      return;
  } else if (initialForestPixels2023 === 0) {
      console.log("No valid forest pixels found for 2023 within the geometry and threshold.");
      console.log("C2");
      return;
  }


  console.log(`Bobiri Forest Reserve (Threshold >= ${treeCoverThreshold}%):`);
  console.log(`Forest cover in 2003: ${area_km2_2003.toFixed(2)} km²`);
  console.log(`Forest cover in 2023: ${area_km2_2023.toFixed(2)} km²`);

  if (area_km2_2023 < area_km2_2003) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
